  const end=total-chartView.offset,start=Math.max(0,end-chartView.count),bars=d.bars.slice(start,end),m=C.metrics(d,cfg.ivWindow),bb=C.bollinger(d.bars.map(b=>b.c),chartView.period,chartView.deviation),range=bars.flatMap(b=>[b.h,b.l]);
