  out.push(...screen.reasons,...screen.pending.map(v=>'Unverified: '+v));
  if(!s.marketCapScreen&&!ticket.cap)out.push('Confirm market cap ≥$30bn');
  if(!ticket.support)out.push('Confirm wave down into previously tested support');
  if(!ticket.sector)out.push('Confirm no biotech/pharma or known binary event');
  if(!ticket.weekly)out.push('Confirm weekly-option liquidity proxy');
  if(!ticket.deliverable)out.push('Confirm standard OCC deliverables');
