  const tools=(r,right)=>right==='C'?'<td class="l"><span class="note" title="BPSX is a put spread; calls are shown for comparison only">View only</span></td>':'<td class="l bpsx-put-actions"><button class="mini lgb" data-bpsx-leg="long" data-conid="'+r.conid+'" aria-label="BUY '+r.strike+' put" aria-pressed="'+(r.conid===s.long)+'" title="Buy this put as the protective long leg"'+(busy?' disabled':'')+'>+</button> <button class="mini lgs" data-bpsx-leg="short" data-conid="'+r.conid+'" aria-label="SELL '+r.strike+' put" aria-pressed="'+(r.conid===s.short)+'" title="Sell this put as the short leg"'+(busy?' disabled':'')+'>−</button></td>';
  const quality=r=>C.quoteQuality(r?{...r,quote:quote(r)}:null,Date.now(),dataMode==='frozen',spot);
  const cell=(r,right)=>'<td class="'+(right==='P'?'bpsx-put-price ':'')+(Number.isFinite(spot)&&r&&(right==='C'?r.strike<spot:r.strike>spot)?'itm':'')+'" title="'+esc(detail(r))+'">'+price(r,'bid')+' / '+price(r,'ask')+'<div class="dim gk">δ '+C.deltaText(quote(r)?.greeks?.delta)+(Number.isFinite(quote(r)?.greeks?.iv)?' · '+(quote(r).greeks.iv*100).toFixed(0)+'% iv':'')+' · '+esc(!resolved(r)&&r?.displayQuote?'Last quote':quote(r)?.status||'Loading')+'</div><div class="bpsx-quote-quality" data-wide="'+/^WIDE/.test(quality(r).label)+'">'+esc(!resolved(r)&&r?.displayQuote?'Retained display — not executable':quality(r).label)+(Number.isFinite(quality(r).width)?' · width $'+quality(r).width.toFixed(2):'')+'</div></td>';
  const marketRow=()=>'<tr class="bpsx-market-row"><td colspan="5">'+esc(share.label)+' <b>$'+fmt(spot)+'</b> · ATM anchor (listed at/below shares) '+fmt(atm)+(outside?' outside this window':'')+'</td></tr>';
