 function patchChain(){recalculate();const node=el?.querySelector('#bpsx-chain-live');if(!node)return;const box=node.querySelector('.bpsx-chain-table'),scroll=box?.scrollTop||0,left=box?.scrollLeft||0,focused=document.activeElement?.closest('[data-bpsx-leg]'),focusLeg=focused?.dataset.bpsxLeg,focusId=focused?.dataset.conid,markup=chainTable();if(node.innerHTML!==markup){const source=node.cloneNode(false);source.innerHTML=markup;syncChainDOM(node,source);}const next=node.querySelector('.bpsx-chain-table');if(next){next.scrollTop=scroll;next.scrollLeft=left;}if(focusId)node.querySelector('[data-bpsx-leg="'+focusLeg+'"][data-conid="'+focusId+'"]')?.focus({preventScroll:true});for(const field of ['bpsx-short','bpsx-long','bpsx-send']){const select=el.querySelector('#'+field);if(select)select.disabled=busy||!(field==='bpsx-send'?putsComplete(selection.chain):chainVisible(selection.chain));}for(const id of ['bpsx-short','bpsx-long'])for(const option of el.querySelector('#'+id)?.options||[]){const r=selection.chain.puts.find(r=>r.conid===Number(option.value));if(r)option.textContent=r.strike+' · δ '+C.deltaText(r.quote?.greeks?.delta)+' · '+(r.quote?.status||r.quoteState||'Loading');}const status=el.querySelector('#bpsx-blockers');if(status)status.textContent=blockers().join(' · ')||'Ready for paper-order confirmation';patchTicket();}
 async function pollChain(){if(pollBusy||busy||document.hidden||!active()||!selection?.chain?.streamId||Date.now()<(selection.retryAt||0))return;const s=selection,id=epoch,sid=s.chain.streamId;pollBusy=true;try{const ch=await request('bpsx_quotes?stream='+encodeURIComponent(sid));if(!current(s,id)||s.chain?.streamId!==sid)return;if(ch.underConid!==s.data.underConid||ch.symbol!==s.symbol||ch.expiry!==s.chain.expiry)throw Error('Streaming chain identity mismatch');acceptChain(ch);if(chainVisible(ch)&&!s.manualLegs&&!s.short&&!s.long&&C.recommend(ch.puts,sharePrice(ch).value,Date.now(),dataMode==='frozen')){auto(true);}else patchChain();}catch(e){if(current(s,id)&&s.chain?.streamId===sid){s.retryAt=Date.now()+3000;s.chain.streamError=e.message;patchChain();if(/stream expired/i.test(e.message)&&!s.recovering){s.recovering=true;try{const ch=await request(chainPath(s,s.chain.expiry));if(!current(s,id)||s.chain?.streamId!==sid)return;if(ch.underConid!==s.data.underConid||ch.symbol!==s.symbol||ch.expiry!==s.chain.expiry)throw Error('Renewed chain identity mismatch');if(current(s,id)&&s.chain?.streamId===sid){acceptChain(ch);message='IB chain session renewed; edited ticket and last observed markets retained.';patchChain();}}catch(retry){if(current(s,id)&&s.chain?.streamId===sid){s.retryAt=Date.now()+10000;s.chain.streamError=retry.message+' — use Reload chain.';patchChain();}}finally{s.recovering=false;}}}}finally{pollBusy=false;}}
