 function auto(keep=false){const s=selection;if(!s?.chain?.puts?.length){message='Load the put chain first.';draw();return;}const focused=document.activeElement?.id,caret=document.activeElement?.selectionStart,p=C.recommend(s.chain.puts,sharePrice(s.chain).value,Date.now(),dataMode==='frozen');s.manualLegs=false;s.short=p?.short.conid||null;s.long=p?.long.conid||null;if(!keep)ticket=empty();revision++;if(p){if(!keep||ticket.credit===''){ticket.autoCredit=true;ticket.credit='';} /* limit = mid credit, as the course works it */message='Pre-selected observed delta '+fmt(p.short.quote.greeks.delta)+' · '+fmt(p.buffer*100)+'% buffer. Review all entry checks.';}else message='No qualifying spread yet — '+C.explain(s.chain.puts,sharePrice(s.chain).value,Date.now(),dataMode==='frozen')+'. No invented prices or Greeks.';draw();revealLegs();if(focused){const input=el.querySelector('#'+CSS.escape(focused));input?.focus({preventScroll:true});if(Number.isInteger(caret)&&input?.setSelectionRange)try{input.setSelectionRange(caret,caret);}catch(_){}}}
